package main

import (
	"fmt"
	"strings"

	"github.com/falcosecurity/plugins/plugins/gvisor/pkg/gvisor"
)

const header = `# gvisor plugin fields

<!-- Generated by tools/genfields from pkg/gvisor/fields.go. Do not edit; run make generate. -->

Fields reuse Falco's standard names wherever the meaning matches, so existing
rule knowledge transfers. A field is absent (` + "`<NA>`" + ` in outputs) when the
event does not carry it, for example ` + "`fd.name`" + ` on ` + "`sentry_execve`" + `.

Differences from Falco's syscall source:

- ` + "`proc.pid`/`proc.ppid`" + ` are ids inside the sandbox, not host pids.
- ` + "`proc.tty`" + ` is approximated from the stdio fds at exec.
- ` + "`fd.name`" + ` for ` + "`connect`" + ` is the remote endpoint (` + "`ip:port`" + `); the local
  side is not reported by gVisor.
- ` + "`evt.arg.*`" + ` values are rendered strings (` + "`O_WRONLY|O_CREAT`" + `, ` + "`AF_PACKET`" + `).
- ` + "`proc.aname`/`proc.aexepath`" + ` require an index; use ` + "`gvisor.anames`" + ` to
  match any ancestor.
- Container metadata (name, image, labels, k8s) is resolved asynchronously.
  A new container's first event waits up to ` + "`metadataWaitMillis`" + ` for it.
- String fields carry the workload's bytes unchanged, so rules match what the
  workload actually ran. Falco escapes control characters when rendering
  outputs (verified with Falco 0.45: a newline in argv appears as ` + "`\\n`" + `),
  so they cannot forge alert lines.

`

type section struct {
	title  string
	prefix []string
}

var sections = []section{
	{"Event", []string{"evt."}},
	{"File descriptor", []string{"fd."}},
	{"Process and user", []string{"proc.", "user.", "group."}},
	{"Container and Kubernetes", []string{"container.", "k8s."}},
	{"gVisor", []string{"gvisor.stats."}},
}

func render() string {
	var b strings.Builder
	b.WriteString(header)
	defs := gvisor.Fields()
	used := map[string]bool{}
	for _, s := range sections {
		title := s.title
		if title == "gVisor" {
			writeTable(&b, "gVisor", filter(defs, used, []string{"gvisor."}, "gvisor.stats."))
			title = "Stats (`evt.type = gvisor_stats`)"
		}
		writeTable(&b, title, filter(defs, used, s.prefix, ""))
	}
	return b.String()
}

func filter(defs []gvisor.FieldDef, used map[string]bool, prefixes []string, exclude string) []gvisor.FieldDef {
	var out []gvisor.FieldDef
	for _, d := range defs {
		if used[d.Name] || (exclude != "" && strings.HasPrefix(d.Name, exclude)) {
			continue
		}
		for _, p := range prefixes {
			if strings.HasPrefix(d.Name, p) {
				out = append(out, d)
				used[d.Name] = true
				break
			}
		}
	}
	return out
}

func writeTable(b *strings.Builder, title string, defs []gvisor.FieldDef) {
	fmt.Fprintf(b, "## %s\n\n| Field | Type | Description |\n|---|---|---|\n", title)
	for _, d := range defs {
		name := d.Name
		switch d.Arg {
		case gvisor.ArgIndex:
			name += "[N]"
		case gvisor.ArgKey:
			name += "[key]"
		}
		typ := d.Type
		if d.IsList {
			typ = "list of " + typ
		}
		fmt.Fprintf(b, "| `%s` | %s | %s |\n", name, typ, strings.ReplaceAll(d.Desc, "|", `\|`))
	}
	b.WriteString("\n")
}
